head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//mouse wheel
(function(a) {
    /**
     * @method
     * @name d
     * @description desc
     * @param {string} b desc
     * @returns
     * @hidden N
     * @exception
     * @example
     */
    function d(b) {
        var c = b || window.event,
            d = [].slice.call(arguments, 1),
            e = 0,
            f = !0,
            g = 0,
            h = 0;
        return
        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************
        b = a.event.fix(c), b.type = "mousewheel", c.wheelDelta && (e = c.wheelDelta / 120), c.detail && (e = -c.detail / 3), h = e, c.axis !== undefined && c.axis === c.HORIZONTAL_AXIS && (
            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************
            h = 0, g = -1 * e), c.wheelDeltaY !== undefined && (h = c.wheelDeltaY / 120), c.wheelDeltaX !== undefined && (g = -1 * c.wheelDeltaX / 120), d.unshift(b, e, g, h), (a.event.dispatch || a.event.handle).apply(this, d);
    };
    var b = ["DOMMouseScroll", "mousewheel"];
    if (a.event.fixHooks)
        for (var c = b.length; c;) a.event.fixHooks[b[c--]] = a.event.mouseHooks;
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    a.event.special.mousewheel = {
        setup: function() {
            if (this.addEventListener)
                for (var a = b.length; a;) this.addEventListener(b[a--], d, !1);

            else this.onmousewheel = d;
        },
        teardown: function() {
            if (this.removeEventListener)
                for (var a = b.length; a;) this.removeEventListener(b[a--], d, !1);

            else this.onmousewheel = null;
        }
    }, a.fn.extend({
        mousewheel: function(a) {
            return a ? this.bind("mousewheel", a) : this.trigger("mousewheel");
        },
        unmousewheel: function(a) {
            return this.unbind("mousewheel", a);
        }
    });
})(jQuery);
//carouselite
(function($) {
    $.jCarouselLite = {
        version: '@VERSION',
        curr: 0
    };
    $.fn.jCarouselLite = function(options) {
        var o = $.extend(true, {}, $.fn.jCarouselLite.defaults, options),
            ceil = Math.ceil,
            mabs = Math.abs;
        this.each(function() {
            var beforeCirc, afterCirc, pageNav, pageNavCount, resize, prepResize, touchEvents, styles = {
                    div: {},
                    ul: {},
                    li: {}
                },
                firstCss = true,
                running = false,
                animCss = o.vertical ? "top" : "left",
                aniProps = {},
                sizeProp = o.vertical ? "height" : "width",
                self = this,
                div = $(this),
                ul = div.find('ul').eq(0),
                tLi = ul.children('li'),
                tl = tLi.length,
                visibleNum = o.visible,
                visibleCeil = ceil(visibleNum),
                visibleFloor = Math.floor(visibleNum),
                start = Math.min(o.start, tl - 1),
                direction = 1,
                activeBtnOffset = 0,
                activeBtnTypes = {},
                startTouch = {},
                endTouch = {},
                axisPrimary = o.vertical ? 'y' : 'x',
                axisSecondary = o.vertical ? 'x' : 'y';
            var init = o.init.call(this, o, tLi);
            if (init === false) {
                return;
            }
            div.data('dirjc', direction);
            div.data(animCss + 'jc', div.css(animCss));
            if (o.circular) {
                beforeCirc = tLi.slice(tl - visibleCeil).clone(true).each(fixIds);
                afterCirc = tLi.slice(0, visibleCeil).clone(true).each(fixIds);
                ul.prepend(beforeCirc).append(afterCirc);
                start += visibleCeil;
                activeBtnOffset = visibleCeil;
            }
            var setActiveBtn = function(i, types) {
                i = ceil(i);
                var $btnsGo, activeBtnIndex = (i - activeBtnOffset) % tl,
                    visEnd = activeBtnIndex + visibleFloor;
                if (types.go) {
                    $btnsGo = $(o.btnGo);
                    $btnsGo.removeClass(o.activeClass).removeClass(o.visibleClass);
                    $btnsGo.eq(activeBtnIndex).addClass(o.activeClass);
                    $btnsGo.slice(activeBtnIndex, activeBtnIndex + visibleFloor).addClass(o.visibleClass);
                    if (visEnd > $btnsGo.length) {
                        $btnsGo.slice(0, visEnd - $btnsGo.length).addClass(o.visibleClass);
                    }
                }
                if (types.pager) {
                    pageNav.removeClass(o.activeClass);
                    pageNav.eq(ceil(activeBtnIndex / visibleNum)).addClass(o.activeClass);
                }
                return activeBtnIndex;
            };
            var li = ul.children('li'),
                itemLength = li.length,
                curr = start;
            $.jCarouselLite.curr = curr;
            var getDimensions = function(reset) {
                var liSize, ulSize, divSize;
                if (reset) {
                    styles.div[sizeProp] = '';
                    styles.li = {
                        width: '',
                        height: ''
                    };
                    return styles;
                }
                liSize = o.vertical ? li.outerHeight(true) : li.outerWidth(true);
                ulSize = liSize * itemLength;
                divSize = liSize * visibleNum;
                styles.div[sizeProp] = divSize + 'px';
                styles.ul[sizeProp] = ulSize + 'px';
                styles.ul[animCss] = -(curr * liSize) + 'px';
                styles.li = {
                    width: li.width(),
                    height: li.height()
                };
                styles.liSize = liSize;
                return styles;
            };
            var setDimensions = function(reset) {
                var css;
                var prelimCss = {
                    div: {
                        visibility: 'visible',
                        position: 'relative',
                        zIndex: 2,
                        left: '0'
                    },
                    ul: {
                        margin: '0',
                        padding: '0',
                        position: 'relative',
                        listStyleType: 'none',
                        zIndex: 1
                    },
                    li: {
                        overflow: o.vertical ? 'hidden' : 'visible',
                        'float': o.vertical ? 'none' : 'left'
                    }
                };
                if (reset) {
                    css = getDimensions(true);
                    div.css(css.div);
                    ul.css(css.ul);
                    li.css(css.li);
                }
                css = getDimensions();
                if (o.autoCSS) {
                    if (firstCss) {
                        $.extend(true, css, prelimCss);
                        firstCss = false;
                    }
                    li.css(css.li);
                    ul.css(css.ul);
                    div.css(css.div);
                }
            };
            setDimensions();
            var advanceCounter = 0,
                autoStop = iterations(tl, o),
                autoScrollBy = typeof o.auto == 'number' ? o.auto : o.scroll;
            var advancer = function() {
                self.setAutoAdvance = setTimeout(function() {
                    if (!autoStop || autoStop > advanceCounter) {
                        direction = div.data('dirjc');
                        go(curr + (direction * autoScrollBy));
                        advanceCounter++;
                        advancer();
                    }
                }, o.timeout);
            };
            $.each(['btnPrev', 'btnNext'], function(index, btn) {
                if (o[btn]) {
                    o['$' + btn] = $.isFunction(o[btn]) ? o[btn].call(div[0]) : $(o[btn]);
                    o['$' + btn].bind('click.jc', function(event) {
                        event.preventDefault();
                        var step = index === 0 ? curr - o.scroll : curr + o.scroll;
                        if (o.directional) {
                            div.data('dirjc', (index ? 1 : -1));
                        }
                        return go(step);
                    });
                }
            });
            if (!o.circular) {
                if (o.btnPrev && start === 0) {
                    o.$btnPrev.addClass(o.btnDisabledClass);
                }
                if (o.btnNext && start + visibleFloor >= itemLength) {
                    o.$btnNext.addClass(o.btnDisabledClass);
                }
            }
            if (o.btnGo) {
                $.each(o.btnGo, function(i, val) {
                    $(val).bind('click.jc', function(event) {
                        event.preventDefault();
                        return go(o.circular ? visibleNum + i : i);
                    });
                });
                activeBtnTypes.go = 1;
            }
            if (o.autoPager) {
                pageNavCount = ceil(tl / visibleNum);
                pageNav = [];
                for (var i = 0; i < pageNavCount; i++) {
                    pageNav.push('<li><a href="#">' + (i + 1) + '</a></li>');
                }
                if (pageNav.length > 1) {
                    pageNav = $('<ul>' + pageNav.join('') + '</ul>').appendTo(o.autoPager).find('li');
                }
                pageNav.find('a').each(function(i) {
                    $(this).bind('click.jc', function(event) {
                        event.preventDefault();
                        var slide = i * visibleNum;
                        if (o.circular) {
                            slide += visibleNum;
                        }
                        return go(slide);
                    });
                });
                activeBtnTypes.pager = 1;
            }
            setActiveBtn(start, activeBtnTypes);
            if (o.mouseWheel && div.mousewheel) {
                div.bind('mousewheel.jc', function(e, d) {
                    return d > 0 ? go(curr - o.scroll) : go(curr + o.scroll);
                });
            }
            if (o.pause && o.auto) {
                div.bind('mouseenter.jc', function() {
                    div.trigger('pauseCarousel.jc');
                }).bind('mouseleave.jc', function() {
                    div.trigger('resumeCarousel.jc');
                });
            }
            if (o.auto) {
                advancer();
            }
            /**
             * @method
             * @name vis
             * @description desc
             * @param
             * @returns
             * @hidden N
             * @exception
             * @example
             */
            function vis() {
                return li.slice(curr).slice(0, visibleCeil);
            };
            $.jCarouselLite.vis = vis;
            /**
             * @method
             * @name go
             * @description desc
             * @param {string} to desc
             * @param {string} settings desc
             * @returns
             * @hidden N
             * @exception
             * @example
             */
            function go(to, settings) {
                if (running) {
                    return false;
                }
                settings = settings || {};
                var prev = curr,
                    direction = to > curr,
                    speed = settings.speed || o.speed,
                    offset = settings.offset || 0;
                if (o.beforeStart) {
                    o.beforeStart.call(div, vis(), direction);
                }
                li.removeClass(o.activeClass);
                if (o.circular) {
                    if (to > curr && to > itemLength - visibleCeil) {
                        curr = curr % tl;
                        to = to - tl;
                        ul.css(animCss, (-curr * styles.liSize) - offset);
                    } else if (to < curr && to < 0) {
                        curr += tl;
                        to += tl;
                        ul.css(animCss, (-curr * styles.liSize) - offset);
                    }
                    curr = to + (to % 1);
                } else {
                    if (to < 0) {
                        to = 0;
                    } else if (to > itemLength - visibleFloor) {
                        to = itemLength - visibleFloor;
                    }
                    curr = to;
                    if (curr === 0 && o.first) {
                        o.first.call(this, vis(), direction);
                    }
                    if (curr === itemLength - visibleFloor && o.last) {
                        o.last.call(this, vis(), direction);
                    }
                    if (o.btnPrev) {
                        o.$btnPrev.toggleClass(o.btnDisabledClass, curr === 0);
                    }
                    if (o.btnNext) {
                        o.$btnNext.toggleClass(o.btnDisabledClass, curr === itemLength - visibleFloor);
                    }
                }
                setActiveBtn(curr, activeBtnTypes);
                $.jCarouselLite.curr = curr;
                if (prev === curr && !settings.force) {
                    if (o.afterEnd) {
                        o.afterEnd.call(div, vis(), direction);
                    }
                    return curr;
                }
                running = true;
                aniProps[animCss] = -(curr * styles.liSize);
                ul.animate(aniProps, speed, o.easing, function() {
                    if (o.afterEnd) {
                        o.afterEnd.call(div, vis(), direction);
                    }
                    running = false;
                });
                li.eq(curr).addClass(o.activeClass);
                return curr;
            };
            div.bind('go.jc', function(e, to, settings) {
                if (typeof to == 'undefined') {
                    to = '+=1';
                }
                var todir = typeof to == 'string' && /(\+=|-=)(\d+)/.exec(to);
                if (todir) {
                    to = todir[1] == '-=' ? curr - todir[2] * 1 : curr + todir[2] * 1;
                } else {
                    to += start;
                }
                go(to, settings);
            }).bind('startCarousel.jc', function(event) {
                clearTimeout(self.setAutoAdvance);
                self.setAutoAdvance = undefined;
                div.trigger('go', '+=' + o.scroll);
                advancer();
                div.removeData('pausedjc').removeData('stoppedjc');
            }).bind('resumeCarousel.jc', function(event, forceRun) {
                if (self.setAutoAdvance) {
                    return;
                }
                clearTimeout(self.setAutoAdvance);
                self.setAutoAdvance = undefined;
                var stopped = div.data('stoppedjc');
                if (forceRun || !stopped) {
                    advancer();
                    div.removeData('pausedjc');
                    if (stopped) {
                        div.removeData('stoppedjc');
                    }
                }
            }).bind('pauseCarousel.jc', function(event) {
                clearTimeout(self.setAutoAdvance);
                self.setAutoAdvance = undefined;
                div.data('pausedjc', true);
            }).bind('stopCarousel.jc', function(event) {
                clearTimeout(self.setAutoAdvance);
                self.setAutoAdvance = undefined;
                div.data('stoppedjc', true);
            }).bind('refreshCarousel.jc', function(event) {
                setDimensions(o.autoCSS);
            }).bind('endCarousel.jc', function() {
                if (self.setAutoAdvance) {
                    clearTimeout(self.setAutoAdvance);
                    self.setAutoAdvance = undefined;
                }
                if (o.btnPrev) {
                    o.$btnPrev.addClass(o.btnDisabledClass).unbind('.jc');
                }
                if (o.btnNext) {
                    o.$btnNext.addClass(o.btnDisabledClass).unbind('.jc');
                }
                if (o.btnGo) {
                    $.each(o.btnGo, function(i, val) {
                        $(val).unbind('.jc');
                    });
                }
                if (o.circular) {
                    li.slice(0, visibleCeil).remove();
                    li.slice(-visibleCeil).remove();
                }
                $.each([animCss + 'jc', 'pausedjc', 'stoppedjc', 'dirjc'], function(i, d) {
                    div.removeData(d);
                });
                div.unbind('.jc');
            });
            touchEvents = {
                touchstart: function(event) {
                    startTouch.x = event.targetTouches[0].pageX;
                    startTouch.y = event.targetTouches[0].pageY;
                    startTouch[animCss] = parseFloat(ul.css(animCss));
                    startTouch.time = +new Date();
                },
                touchmove__function: function(event) {
                    var tlength = event.targetTouches.length;
                    if (tlength === 1) {
                        event.preventDefault();
                        endTouch.x = event.targetTouches[0].pageX;
                        endTouch.y = event.targetTouches[0].pageY;
                        aniProps[animCss] = startTouch[animCss] + (endTouch[axisPrimary] - startTouch[axisPrimary]);
                        ul.css(aniProps);
                    } else {
                        endTouch = startTouch;
                    }
                },
                touchend: function(event) {
                    if (!endTouch.x) {
                        return;
                    }
                    var pxDelta = startTouch[axisPrimary] - endTouch[axisPrimary],
                        pxAbsDelta = mabs(pxDelta),
                        primaryAxisGood = pxAbsDelta > o.swipeThresholds[axisPrimary],
                        secondaryAxisGood = mabs(startTouch[axisSecondary] - endTouch[axisSecondary]) < o.swipeThresholds[axisSecondary],
                        timeDelta = +new Date() - startTouch.time,
                        quickSwipe = timeDelta < o.swipeThresholds.time,
                        operator = pxDelta > 0 ? '+=' : '-=',
                        to = operator + o.scroll,
                        swipeInfo = {
                            force__true: force__true
                        };
                    if (quickSwipe && primaryAxisGood && secondaryAxisGood) {
                        swipeInfo.speed = o.speed / 2;
                    } else if ((!quickSwipe && pxAbsDelta < styles.liSize / 2) || !primaryAxisGood || (quickSwipe && !secondaryAxisGood)) {
                        to = '+=0';
                    } else if (!quickSwipe && pxAbsDelta > styles.liSize / 2) {

                        // ********************************************************************
                        // [WebSquare 전환 추가] 원본 소스와 비교 필요
                        // 
                        // ********************************************************************

                        to = Math.round(pxAbsDelta / styles.liSize);
                        to = operator + (to > o.visible ? o.visible__to : X);
                        swipeInfo.offset = pxDelta;
                    }
                    div.trigger('go.jc', [to, swipeInfo]);
                    endTouch = {};
                }
            };
            if ('ontouchend' in document && o.swipe) {
                div.bind('touchstart touchmove touchend', function(event) {
                    event = event.originalEvent;
                    touchEvents[event.type](event);
                });
            }
            if (o.responsive) {
                prepResize = o.autoCSS;
                $(window).bind('resize', function(event) {
                    if (prepResize) {
                        ul.width(ul.width() * 2);
                        prepResize = false;
                    }
                    clearTimeout(resize);
                    resize = setTimeout(function() {
                        div.trigger('refreshCarousel');
                        prepResize = o.autoCSS;
                    }, 100);
                });
            }
        });
        return this;
    };
    $.fn.jCarouselLite.defaults = {
        autoCSS: true,
        btnPrev: null,
        btnNext: null,
        btnGo: null,
        autoPager: null,
        btnDisabledClass: 'disabled',
        activeClass: 'active',
        visibleClass: 'vis',
        mouseWheel: false,
        speed: 200,
        easing: null,
        timeout: 4000,
        auto: false,
        directional: false,
        autoStop: false,
        pause__true: pause__true,
        vertical: false,
        circular: true,
        visible__3: visible__3,
        start: 0,
        scroll: 1,
        responsive__false: responsive__false,
        swipe__true: swipe__true,
        swipeThresholds: {
            x: 80,
            y: 120,
            time__150: time__150
        },
        init: function() {

        },
        first: null,
        last: null,
        beforeStart: null,
        afterEnd: null
    };
    /**
     * @method
     * @name iterations
     * @description desc
     * @param {string} itemLength desc
     * @param {string} options desc
     * @returns
     * @hidden N
     * @exception
     * @example
     */
    function iterations(itemLength, options) {
        return options.autoStop && (options.circular ? options.autoStop : Math.min(itemLength, options.autoStop));
    };
    /**
     * @method
     * @name fixIds
     * @description desc
     * @param {string} i desc
     * @returns
     * @hidden N
     * @exception
     * @example
     */
    function fixIds(i) {
        if (this.id) {
            this.id += i;
        }
    };
})(jQuery);
//uniform [css]
(function(a) {
    a.uniform = {
        options: {
            selectClass: "selector",
            radioClass: "radio",
            checkboxClass: "checker",
            fileClass: "uploader",
            filenameClass: "filename",
            fileBtnClass: "action",
            fileDefaultText: "No file selected",
            fileBtnText: "Choose File",
            checkedClass: "checked",
            focusClass: "focus",
            disabledClass: "disabled",
            buttonClass: "button",
            activeClass: "active",
            hoverClass: "hover",
            useID: true,
            idPrefix: "uniform",
            resetSelector: false,
            autoHide__true: autoHide__true
        },
        elements: []
    };
    if (a.browser.msie && a.browser.version < 7) {
        a.support.selectOpacity = false;
    } else {
        a.support.selectOpacity = true;
    }
    a.fn.uniform = function(k) {
        k = a.extend(a.uniform.options, k);
        var d = this;
        if (k.resetSelector != false) {
            a(k.resetSelector).mouseup(function() {
                /**
                 * @method
                 * @name l
                 * @description desc
                 * @param
                 * @returns
                 * @hidden N
                 * @exception
                 * @example
                 */
                function l() {
                    a.uniform.update(d);
                };
                setTimeout(l, 10);
            });
        }
        /**
         * @method
         * @name j
         * @description desc
         * @param {string} l desc
         * @returns
         * @hidden N
         * @exception
         * @example
         */
        function j(l) {
            $el = a(l);
            $el.addClass($el.attr("type"));
            b(l);
        };
        /**
         * @method
         * @name g
         * @description desc
         * @param {string} l desc
         * @returns
         * @hidden N
         * @exception
         * @example
         */
        function g(l) {
            a(l).addClass("uniform");
            b(l);
        };
        /**
         * @method
         * @name i
         * @description desc
         * @param {string} o desc
         * @returns
         * @hidden N
         * @exception
         * @example
         */
        function i(o) {
            var m = a(o);
            var p = a("<div>"),
                l = a("<span>");
            p.addClass(k.buttonClass);
            if (k.useID && m.attr("id") != "") {
                p.attr("id", k.idPrefix + "-" + m.attr("id"));
            }
            var n;
            if (m.is("a") || m.is("button")) {
                n = m.text();
            } else {
                if (m.is(":submit") || m.is(":reset") || m.is("input[type=button]")) {
                    n = m.attr("value");
                }
            }
            n = n == "" ? m.is(":reset") ? "Reset" : "Submit" : n;
            l.html(n);
            m.css("opacity", 0);
            m.wrap(p);
            m.wrap(l);
            p = m.closest("div");
            l = m.closest("span");
            if (m.is(":disabled")) {
                p.addClass(k.disabledClass);
            }
            p.bind({
                "mouseenter.uniform": function() {
                    p.addClass(k.hoverClass);
                },
                "mouseleave.uniform": function() {
                    p.removeClass(k.hoverClass);
                    p.removeClass(k.activeClass);
                },
                "mousedown.uniform touchbegin.uniform": function() {
                    p.addClass(k.activeClass);
                },
                "mouseup.uniform touchend.uniform": function() {
                    p.removeClass(k.activeClass);
                },
                "click.uniform touchend.uniform": function(r) {
                    if (a(r.target).is("span") || a(r.target).is("div")) {
                        if (o[0].dispatchEvent) {
                            var q = document.createEvent("MouseEvents");
                            q.initEvent("click", true, true);
                            o[0].dispatchEvent(q);
                        } else {
                            o[0].click();
                        }
                    }
                }
            });
            o.bind({
                "focus.uniform": function() {
                    p.addClass(k.focusClass);
                },
                "blur.uniform": function() {
                    p.removeClass(k.focusClass);
                }
            });
            a.uniform.noSelect(p);
            b(o);
        };
        /**
         * @method
         * @name e
         * @description desc
         * @param {string} o desc
         * @returns
         * @hidden N
         * @exception
         * @example
         */
        function e(o) {
            var m = a(o);
            var p = a("<div />"),
                l = a("<span />");
            if (!m.css("display") == "none" && k.autoHide) {
                p.hide();
            }
            p.addClass(k.selectClass);
            if (k.useID && o.attr("id") != "") {
                p.attr("id", k.idPrefix + "-" + o.attr("id"));
            }
            var n = o.find(":selected:first");
            if (n.length == 0) {
                n = o.find("option:first");
            }
            l.html(n.html());
            o.css("opacity", 0);
            o.wrap(p);
