//slide show simple
jQuery.fn.simple_slideshow = function(settings) {
    var simple_slideshow = $(this);
    var itemsCollection = simple_slideshow.find('li');
    var current = 0;
    var paused = 0;
    var defaults = {
        interval: 1000,
        is_paused: true,
        nav: false,
        hover_event: true
    };
    var options = $.extend(defaults, settings);
    var interval;
    interval = options.interval;
    var nav = options.nav;
    itemsCollection.each(function() {
        if ($(this).height() > simple_slideshow.height()) {
            simple_slideshow.height($(this).height());
        }
    });
    itemsCollection.hide().filter(":eq(0)").show().add("li");
    itemsCollection.hover(function() {
        paused = 1;
    }, function() {
        paused = 0;
    });
    /**
     * @method
     * @name simple_slide_timer
     * @description desc
     * @param
     * @returns
     * @hidden N
     * @exception
     * @example
     */
    function simple_slide_timer() {
        if (options.is_paused == true && paused) {
            return;
        }
        current = current++ % itemsCollection.size();
        simple_slide_act(current);
    };
    /**
     * @method
     * @name simple_slide_act
     * @description desc
     * @param {string} o desc
     * @returns
     * @hidden N
     * @exception
     * @example
     */
    function simple_slide_act(o) {
        // effect 여기 수정
        simple_slideshow.find("li").hide();
        simple_slideshow.find("li:eq(" + o + ")").show();
        //
        if ($(nav).find("a").length > 0) {
            $(nav).find("a").removeClass("active");
            $(nav).find("a").eq(o).addClass("active");
        }
    };
    //nav action
    if ($(nav).find("a").length > 0) {
        var nav_e;
        if (options.hover_event == true) nav_e = "mouseover";

        else nav_e = "click";
        $(nav).find("a").each(function(i) {
            $(this).data('idx', i);
        });
        $(nav).find("a").bind(nav_e, function() {
            paused = 1;
            var idx = $(this).data('idx');
            simple_slide_act(idx);
            current = idx;
        });
        $(nav).find("a").mouseout(function() {
            paused = 0;
        });
        //init
        $(nav).find("a").bind("click focusin", function(e) {
            e.preventDefault();
        });
        $(nav).find("a").eq(0).addClass("active");
    }
    if (itemsCollection.length > 1) {
        setInterval(simple_slide_timer, interval);
    }
};
jQuery.fn.simple_slideshow2 = function(settings) {
    var simple_slideshow2 = $(this);
    var itemsCollection = simple_slideshow2.find('li');
    var current = 0;
    var paused = 0;
    var defaults = {
        interval: 1000,
        is_paused: true,
        btnp: false,
        btnn: false,
        hover_event: true
    };
    var options = $.extend(defaults, settings);
    var interval;
    interval = options.interval;
    var btnp = options.btnp;
    var btnn = options.btnn;
    itemsCollection.each(function() {
        if ($(this).height() > simple_slideshow2.height()) {
            simple_slideshow2.height($(this).height());
        }
    });
    itemsCollection.hide().filter(":eq(0)").show().add("li");
    itemsCollection.hover(function() {
        paused = 1;
    }, function() {
        paused = 0;
    });
    /**
     * @method
     * @name simple_slide_timer
     * @description desc
     * @param
     * @returns
     * @hidden N
     * @exception
     * @example
     */
    function simple_slide_timer() {
        if (options.is_paused == true && paused) {
            return;
        }
        current = current++ % itemsCollection.size();
        simple_slide_act(current);
    };
    /**
     * @method
     * @name simple_slide_act
     * @description desc
     * @param {string} o desc
     * @returns
     * @hidden N
     * @exception
     * @example
     */
    function simple_slide_act(o) {
        // effect 여기 수정
        simple_slideshow2.find("li").hide();
        simple_slideshow2.find("li:eq(" + o + ")").show();
        //

    };
    //btnp action
    if ($(btnp).length > 0) {
        var btn_e;
        if (options.hover_event == true) btn_e = "mouseover";

        else btn_e = "click";
        $(btnp).bind(btn_e, function() {
            paused = 1;
            var idx = current - 1;
            if (idx < 0) idx = itemsCollection.size() - 1;
            simple_slide_act(idx);
            current = idx;
        });
        $(btnp).mouseout(function() {
            paused = 0;
        });
        //init
        $(btnp).bind("click focusin", function(e) {
            e.preventDefault();
        });
    }
    //btnn action
    if ($(btnn).length > 0) {
        var btn_e;
        if (options.hover_event == true) btn_e = "mouseover";

        else btn_e = "click";
        $(btnn).bind(btn_e, function() {
            paused = 1;
            var idx = current + 1;
            if (idx >= itemsCollection.size()) idx = 0;
            simple_slide_act(idx);
            current = idx;
        });
        $(btnn).mouseout(function() {
            paused = 0;
        });
        //init
        $(btnn).bind("click focusin", function(e) {
            e.preventDefault();
        });
    }
    if (itemsCollection.length > 1) {
        setInterval(simple_slide_timer, interval);
    }
};
jQuery.fn.zoom = function(settings) {
    var target = $(this);
    var defaults = {
        btn_in: '.zoom_btn-in',
        btn_out: '.zoom_btn-out',
        arr: new Array(1, 1.2, 1.5, 1.8, 2, 2.5, 3, 4)
    };
    var options = $.extend(defaults, settings);
    var cur = 0;
    var tot = options.arr.length;

    //event

    $(options.btn_in).bind('click', function() {
        zoomin();
    });
    $(options.btn_out).bind('click', function() {
        zoomout();
    });
    /**
     * @method
     * @name zoomin
     * @description desc
     * @param
     * @returns
     * @hidden N
     * @exception
     * @example
     */
    function zoomin() {
        cur++;
        if (cur > tot - 1) cur = 0;
        target.css("zoom", options.arr[cur]);
    };
    /**
     * @method
     * @name zoomout
     * @description desc
     * @param
     * @returns
     * @hidden N
     * @exception
     * @example
     */
    function zoomout() {
        cur--;
        if (cur < 0) cur = 0;
        target.css("zoom", options.arr[cur]);
    };
};
